<?php require_once __DIR__.'/../includes/functions.php'; require_login(); $u=current_user(); $s=db()->prepare("SELECT * FROM orders WHERE customer_id=? ORDER BY created_at DESC");$s->execute([$u['id']]);$orders=$s->fetchAll(); ?><!doctype html><html lang="id"><head><?php include __DIR__.'/../includes/head.php';?></head><body><?php include __DIR__.'/../includes/header.php';?><main class="content"><div class="page-head"><div><p class="eyebrow">CUSTOMER</p><h1>Pesanan Saya</h1></div><a class="btn" href="../order.php">+ Buat Pesanan</a></div><div class="table-wrap"><table><tr><th>Order</th><th>Total</th><th>Status</th><th></th></tr><?php foreach($orders as $o):?><tr><td><?=e($o['order_number'])?></td><td>Rp <?=number_format($o['total_amount'],0,',','.')?></td><td><span class="badge"><?=e(str_replace('_',' ',$o['status']))?></span></td><td><a href="order-detail.php?id=<?=$o['id']?>">Detail</a></td></tr><?php endforeach;?></table></div></main></body></html>